"""Blender-only isolated frame worker; request generated by AGR sequence runner."""
import json
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from agr.blender_render_npr_frame import render_frame

if __name__=='__main__':
    args=sys.argv[sys.argv.index('--')+1:]
    if len(args)!=1:raise ValueError('One frame request required')
    request=json.loads(Path(args[0]).read_text(encoding='utf-8'))
    segment=Path(request['segment'])
    render_frame(request['scene'],json.loads(segment.read_text(encoding='utf-8')),
                 request['output'],request['frame'],manifest_dir=segment.parent,
                 allow_partial=request['allow_partial'])
